import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787002545000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LINKWARDEN_URL</code></td><td>yes</td><td>—</td><td>Base URL, e.g. <code>https://links.example.net</code> — <strong>without</strong> <code>/api/v1</code></td></tr><tr><td><code>LINKWARDEN_TOKEN</code></td><td>yes</td><td>—</td><td>Access token from Settings → Access Tokens</td></tr><tr><td><code>LINKWARDEN_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the 11 read tools</td></tr><tr><td><code>LINKWARDEN_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, for this connection only</td></tr></tbody></table><p>The full reference with formats is in <a href="/reference/environment">Environment variables</a>.</p><h2 id="linkwarden-url" tabindex="-1"><code>LINKWARDEN_URL</code> <a class="header-anchor" href="#linkwarden-url" aria-label="Permalink to “LINKWARDEN_URL”">​</a></h2><p>The base URL of the instance. A trailing slash is stripped, and a URL that already carries <code>/api/v1</code> is normalised — the client appends the prefix itself, and since redirects are never followed the resulting 308 would otherwise be an opaque failure.</p><p>The server refuses to start if the URL:</p><ul><li>does not parse,</li><li>uses a scheme other than <code>http:</code> or <code>https:</code>,</li><li>contains credentials (<code>https://user:pw@…</code>) — use <code>LINKWARDEN_TOKEN</code> instead.</li></ul><p>It warns, but continues, when the URL is plain <code>http:</code> to a non-loopback host: the token would travel unencrypted.</p><h2 id="linkwarden-token" tabindex="-1"><code>LINKWARDEN_TOKEN</code> <a class="header-anchor" href="#linkwarden-token" aria-label="Permalink to “LINKWARDEN_TOKEN”">​</a></h2><p>The access token. It is <strong>deleted from the process environment</strong> as soon as it has been read, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>Linkwarden&#39;s tokens are NextAuth JWTs and start with <code>ey</code>. A value that does not gets a warning at startup — usually it means a session cookie or a password was pasted in by mistake, and the warning arrives before the first confusing 401.</p><h2 id="linkwarden-read-only" tabindex="-1"><code>LINKWARDEN_READ_ONLY</code> <a class="header-anchor" href="#linkwarden-read-only" aria-label="Permalink to “LINKWARDEN_READ_ONLY”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>The 17 write tools are <strong>not registered at all</strong> — they do not appear in <code>tools/list</code>. This is a stronger guarantee than refusing them at call time: a model cannot ask for a tool it cannot see, so nothing depends on the model respecting an instruction.</p><p>Worth pairing with a Linkwarden account that only has read access to the collections it is shared into, so the restriction holds on both ends.</p><h2 id="linkwarden-insecure-tls" tabindex="-1"><code>LINKWARDEN_INSECURE_TLS</code> <a class="header-anchor" href="#linkwarden-insecure-tls" aria-label="Permalink to “LINKWARDEN_INSECURE_TLS”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">LINKWARDEN_INSECURE_TLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>Accepts self-signed certificates. This is a <strong>scoped undici dispatcher</strong>, not <code>NODE_TLS_REJECT_UNAUTHORIZED</code> — certificate validation stays on for everything else in the process.</p><p>Prefer a proper internal CA. If your instance runs on an internal domain with a private CA, adding that CA to the trust store (or <code>NODE_EXTRA_CA_CERTS</code>) keeps validation intact and is barely more work.</p><h2 id="only-the-exact-string-true" tabindex="-1">Only the exact string <code>true</code> <a class="header-anchor" href="#only-the-exact-string-true" aria-label="Permalink to “Only the exact string true”">​</a></h2><p>All boolean flags are compared against the literal string <code>true</code>. <code>True</code>, <code>1</code> and <code>yes</code> are all off. A typo therefore cannot silently disable certificate validation — it fails closed.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};